python3 -c "
import pathlib
p = pathlib.Path('crates/elephc-magician/src/interpreter/builtins/filesystem/glob.rs')
t = p.read_text()
t = t.replace('''        values.warning(
            \"Warning: glob(): At least one of the passed flags is invalid or not supported \"
            \"on this platform\\\\n\",
        )?;''', '''        values.warning(concat!(
            \"Warning: glob(): At least one of the passed flags is invalid or not supported \",
            \"on this platform\\\\n\"
        ))?;''')
t = t.replace('''            let flags = values.to_int(*flags)?;
            eval_glob_result(*pattern, flags, values)''', '''            let flags = eval_int_value(*flags, values)?;
            eval_glob_result(*pattern, flags, values)''')
t = t.replace('''            let flags = eval_expr(flags, context, scope, values)?;
            (pattern, values.to_int(flags)?)''', '''            let flags = eval_expr(flags, context, scope, values)?;
            (pattern, eval_int_value(flags, values)?)''')
p.write_text(t)
print('patched')
"; cargo build -p elephc-magician 2>&1 | grep -E "^error|-->" | head -20: patched --> crates/elephc-magician/src/interpreter/builtins/filesystem/glob.rs:194:31
